import React from 'react';
import { } from 'lucide-react';

const MyApplications = () => {
  const applications = [
    { id: 1, company: 'Tech Solutions', role: 'Frontend Developer', status: 'Pending', date: '2026-03-25' },
    { id: 2, company: 'Innovation Hub', role: 'Mobile App Intern', status: 'Accepted', date: '2026-03-10' },
  ];

  const getStatusStyle = (status) => {
    if (status === 'Accepted') return { color: '#10b981', bg: '#ecfdf5' };
    if (status === 'Refused') return { color: '#ef4444', bg: '#fef2f2' };
    return { color: '#f59e0b', bg: '#fffbeb' };
  };

  return (
    <div style={{ padding: '40px', maxWidth: '900px', margin: '0 auto' }}>
      <h2 style={{ color: '#4a3f6b', marginBottom: '25px' }}>My Applications</h2>
      <div style={{ backgroundColor: 'white', borderRadius: '15px', overflow: 'hidden', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead style={{ backgroundColor: '#f9fafb' }}>
            <tr>
              <th style={{ padding: '15px', color: '#6b7280' }}>Company</th>
              <th style={{ padding: '15px', color: '#6b7280' }}>Role</th>
              <th style={{ padding: '15px', color: '#6b7280' }}>Date</th>
              <th style={{ padding: '15px', color: '#6b7280' }}>Status</th>
            </tr>
          </thead>
          <tbody>
            {applications.map(app => (
              <tr key={app.id} style={{ borderTop: '1px solid #eee' }}>
                <td style={{ padding: '15px', fontWeight: 'bold' }}>{app.company}</td>
                <td style={{ padding: '15px' }}>{app.role}</td>
                <td style={{ padding: '15px', color: '#666' }}>{app.date}</td>
                <td style={{ padding: '15px' }}>
                  <span style={{ 
                    padding: '5px 12px', borderRadius: '20px', fontSize: '12px', fontWeight: 'bold',
                    color: getStatusStyle(app.status).color, backgroundColor: getStatusStyle(app.status).bg 
                  }}>
                    {app.status}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

export default MyApplications;
